import java.util.Scanner;

public class RatingProgram {
    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        System.out.print("Please enter a rating out of 10: ");
        int rating = scanner.nextInt();

        if (rating >= 10) {
            System.out.println("Rating: 10/10");
        } else if (rating >= 8) {
            System.out.println("Rating: 8/10");
        } else if (rating >= 6) {
            System.out.println("Rating: 6/10");
        } else if (rating >= 4) {
            System.out.println("Rating: 4/10");
        } else {
            System.out.println("Rating: " + rating + "/10");
        }

        scanner.close();
    }
}
```

